/**
 * @name Taint to subprocess calls in pyarrow
 * @description Track data flow from function parameters to subprocess command arguments
 * @kind path-problem
 * @problem.severity warning
 * @id pyarrow/tainted-subprocess-call
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SubprocessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["run", "Popen", "call", "check_call", "check_output"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SubprocessFlow = TaintTracking::Global<SubprocessConfig>;
import SubprocessFlow::PathGraph

from SubprocessFlow::PathNode source, SubprocessFlow::PathNode sink
where SubprocessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Tainted data from parameter flows into subprocess call $@.", sink.getNode(), "subprocess"

/**
 * @name Taint from external input to filesystem paths in pyarrow
 * @description Track flow from function parameters to filesystem path arguments
 * @kind path-problem
 * @problem.severity warning
 * @id pyarrow/tainted-path-to-filesystem
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module FsPathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("os").getMember(["open", "remove", "unlink"]).getACall() or
        call = API::moduleImport("os.path").getMember(["join", "dirname", "basename"]).getACall() or
        call = API::moduleImport("pathlib").getMember(["Path"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module FsPathFlow = TaintTracking::Global<FsPathConfig>;
import FsPathFlow::PathGraph

from FsPathFlow::PathNode source, FsPathFlow::PathNode sink
where FsPathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Function parameter flows into filesystem path $@.", sink.getNode(), "path"
